function bagPhoto(id){return data('photo').filter(p=>p.beanId===id).sort((a,b)=>b.created.localeCompare(a.created))[0]?.image||'';}
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let sheetOrigin=null,closingSheet=false;
function morphSheet(source){
 sheetOrigin=source?.getBoundingClientRect();const d=$('#dialog');
 if(!sheetOrigin||reduceMotion())return;
 const to=d.getBoundingClientRect(),from=sheetOrigin;
 d.animate([{transform:`translate(${from.x+from.width/2-to.x-to.width/2}px,${from.y+from.height/2-to.y-to.height/2}px) scale(${Math.max(.15,from.width/to.width)},${Math.max(.15,from.height/to.height)})`,opacity:.25,borderRadius:'24px'},{transform:'none',opacity:1,borderRadius:getComputedStyle(d).borderRadius}],{duration:340,easing:'cubic-bezier(.2,.75,.2,1)'});
}
async function closeSheet(){
 if(closingSheet)return;closingSheet=true;const d=$('#dialog');
 try{if(sheetOrigin&&!reduceMotion()&&d.open){const to=d.getBoundingClientRect(),from=sheetOrigin;await d.animate([{transform:'none',opacity:1},{transform:`translate(${from.x+from.width/2-to.x-to.width/2}px,${from.y+from.height/2-to.y-to.height/2}px) scale(${Math.max(.15,from.width/to.width)},${Math.max(.15,from.height/to.height)})`,opacity:0}],{duration:200,easing:'ease-in'}).finished;}d.close();}finally{closingSheet=false;sheetOrigin=null;}
}
function grindKey(r){return JSON.stringify([r.equipment.id,r.bean.id,r.dose,r.preference,r.drink,r.request?.strength]);}
function draftGrind(r){return grindDrafts.get(grindKey(r))??String(r.grindData?.value??r.grindData?.start??'');}
function usableScale(e){const s=grindScale(e);return s&&Number.isFinite(s.min)&&Number.isFinite(s.max)&&Number.isFinite(s.step)&&s.step>0?s:null;}
function grindFace(r){
 const scale=usableScale(r.equipment),value=draftGrind(r),valid=scale&&value!==''&&Number.isFinite(Number(value));
 return `<div class="grind-instrument ${scale?'':'manual-reference'}"><div class="grind-setting-row">${scale?`<button type="button" id="grind-down" aria-label="${t('Decrease grind setting')}">−</button>`:''}<button type="button" class="grind-readout" id="grind-readout" aria-label="${t('Edit grind setting')}"><small>${t('Grind setting')}</small><strong>${escape(value||'—')}</strong><span>${t('Edit')} <span aria-hidden="true">›</span></span></button>${scale?`<button type="button" id="grind-up" aria-label="${t('Increase grind setting')}">+</button>`:''}</div>${scale?`<input id="grind-range" type="range" min="${scale.min}" max="${scale.max}" step="${scale.step}" value="${valid?value:scale.min}" aria-label="${t('Grind setting')}" aria-valuetext="${escape(value||t('Not set'))}"><p class="grind-direction">${scale.finer==='lower'?t('Finer ← → Coarser'):t('Coarser ← → Finer')}</p>`:''}</div><p class="grind-status">${grindDrafts.has(grindKey(r))?t('Unsaved trial · not yet brewed'):value?t('Starting reference · confirm on your grinder'):t('Set your own reference')}</p>`;
}
function homeCupHTML(e,b,resume){
 let r;try{r=recommend(e,b,selected.preference,selected.dose,data('brew'),{drink:selected.drink,strength:selected.strength});}catch{r=null;}
 const beans=data('bean'),index=beans.findIndex(x=>x.id===b.id);
 return `<section class="panel next-cup" id="continue-card"><div class="bag-stage" aria-label="${t("Choose a bag")}">${beans.length>1?`<button type="button" id="previous-bag" aria-label="${t("Previous bag")}">‹</button>`:''}<div class="bag-slide">${beanObject(b)}<h2>${escape(b.name)}</h2><p class="bean-caption">${escape(b.batch)} · ${escape(t(roasts[b.roast]))}</p></div>${beans.length>1?`<button type="button" id="next-bag" aria-label="${t("Next bag")}">›</button>`:''}</div><div class="bag-dots" aria-label="${t("Your bags")}">${beans.map((x,i)=>`<button type="button" data-select-bag="${i}" aria-label="${escape(t('Select {name}',{name:x.name}))}" aria-pressed="${i===index}"></button>`).join('')}</div>${r?grindFace(r):`<p class="muted">${t("Confirm your setup and roast level below.")}</p>`}${resume?`<p class="last-cup-line">${t("Last cup ·")} ${escape(t(tastes[resume.feedback.taste]))} · ${clockText(resume.feedback.seconds)}</p>`:''}<button type="button" class="primary" id="continue-brew">${t("Brew this cup")} <span aria-hidden="true">→</span></button></section>`;
}
function currentPreview(){const f=$('#brew-form');if(!f)return recipe;const v=Object.fromEntries(new FormData(f));try{return recommend(data('equipment').find(e=>e.id===v.equipment),data('bean').find(b=>b.id===v.bean),v.preference,Number(v.dose),data('brew'),{drink:v.drink,strength:v.strength});}catch{return null;}}
function bindRitual(){
 const r=recipe||currentPreview();if($('#edit-grind'))$('#edit-grind').onclick=()=>editGrind(recipe,$('#edit-grind'));
 if($('#grind-readout')&&r)$('#grind-readout').onclick=()=>editGrind(r,$('#grind-readout'));
 const scale=r&&usableScale(r.equipment),host=$('.grind-instrument');
 if(scale&&host){
  const update=n=>{const value=Number((scale.min+Math.min(Math.floor((scale.max-scale.min)/scale.step+1e-8),Math.round((Math.max(scale.min,Math.min(scale.max,n))-scale.min)/scale.step))*scale.step).toFixed(8));if(value>scale.max)return;grindDrafts.set(grindKey(r),String(value));$('#grind-range').value=value;$('#grind-range').setAttribute('aria-valuetext',String(value));host.querySelector('#grind-readout strong').textContent=value;$('.grind-status').textContent=t('Unsaved trial · not yet brewed');};
  const step=n=>update((Number(draftGrind(r))||scale.min)+n*scale.step);
  $('#grind-down').onclick=()=>step(-1);$('#grind-up').onclick=()=>step(1);
  $('#grind-range').oninput=e=>update(Number(e.target.value));
 }
 const beans=data('bean'),stage=$('.bag-stage');let switching=false;
 const select=async(index,direction)=>{if(switching||index<0||index>=beans.length||beans[index].id===selected.bean)return;switching=true;const slide=$('.bag-slide');if(slide&&!reduceMotion())await slide.animate([{transform:getComputedStyle(slide).transform,opacity:1},{transform:`translateX(${-direction*100}%)`,opacity:0}],{duration:170,easing:'ease-in'}).finished;selected.bean=beans[index].id;recipe=null;elapsed=0;timerStart=null;render();const next=$('.bag-slide');if(next&&!reduceMotion())next.animate([{transform:`translateX(${direction*100}%)`,opacity:0},{transform:'none',opacity:1}],{duration:240,easing:'ease-out'});};
 const index=()=>Math.max(0,beans.findIndex(b=>b.id===($('#brew-form')?.elements.bean.value||selected.bean)));
 if($('#previous-bag'))$('#previous-bag').onclick=()=>select((index()-1+beans.length)%beans.length,-1);
 if($('#next-bag'))$('#next-bag').onclick=()=>select((index()+1)%beans.length,1);
 document.querySelectorAll('[data-select-bag]').forEach(b=>b.onclick=()=>select(Number(b.dataset.selectBag),Number(b.dataset.selectBag)>index()?1:-1));
 if(stage&&beans.length>1){let start=null;stage.onpointerdown=e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId);};stage.onpointermove=e=>{if(!start||reduceMotion())return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>Math.abs(dy))stage.querySelector('.bag-slide').style.transform=`translateX(${Math.max(-160,Math.min(160,dx))}px)`;};stage.onpointerup=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy))select((index()+(dx<0?1:-1)+beans.length)%beans.length,dx<0?1:-1);else stage.querySelector('.bag-slide').style.transform='';};stage.onpointercancel=()=>{start=null;stage.querySelector('.bag-slide').style.transform='';};}
}
function editGrind(r,source){
 const scale=usableScale(r.equipment),value=draftGrind(r);
 modal(`<p class="eyebrow">${escape(r.bean.name)} · ${escape(r.equipment.grinder)}</p><h2>${t("Your next grind")}</h2><form id="grind-form">${input(t("Setting on your grinder"),'setting',value,'text','maxlength="100" required')}<p class="field-help">${scale?escape(t('Your scale: {min}–{max}, steps of {step}. {calibration}',{min:scale.min,max:scale.max,step:scale.step,calibration:r.equipment.calibration||t('Use your confirmed zero reference.')})):t("Copy the full setting, including turns or inner-ring offsets. A dial needs a confirmed range and step in Setup.")}</p><p class="muted">${t("A plan for the next cup. Confirm what you actually used when saving your brew.")}</p><div class="actions"><button class="primary">${t("Use for this cup")}</button><button type="button" id="reset-grind">${t("Reset")}</button></div></form>`);
 $('#dialog').classList.add('grind-dialog');morphSheet(source);
 $('#grind-form').onsubmit=singleSubmit(async e=>{e.preventDefault();const value=e.target.elements.setting.value.trim();try{parseGrind(r.equipment,value);grindDrafts.set(grindKey(r),value);await closeSheet();render();}catch(error){toast(error.message);}});
 $('#reset-grind').onclick=async()=>{grindDrafts.delete(grindKey(r));await closeSheet();render();};
}
async function storePhoto(beanId,image){
 const previous=data('photo').filter(x=>x.beanId===beanId),created=new Date(Math.max(Date.now(),...previous.map(x=>Date.parse(x.created)+1))).toISOString(),photo={id:crypto.randomUUID(),beanId,image,created};
 await merge([{id:photo.id,kind:'photo',created,payload:JSON.stringify(photo)}],scope());
 // A replacement/removal purges old image bytes; the empty latest record is a tombstone for older backups.
 await new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');for(const p of previous)tx.objectStore('entries').delete([scope(),p.id]);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});entries=await list(scope());scheduleAccountSync();
}
function editPhoto(beanId,onUse){
 const existing=beanId?bagPhoto(beanId):'',source=beanId?document.querySelector(`[data-photo-bean="${beanId}"]`):$('#add-bag-photo');let img=null,encoded=existing,serial=0,savingPhoto=false;
 modal(`<p class="eyebrow">${t("YOUR BAG, ON YOUR DEVICE")}</p><h2>${t("A familiar face on the shelf.")}</h2><p class="muted">${t("Choose a photo or use your phone camera. Adjust the crop below.")}</p><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"><div class="photo-crop"><canvas id="photo-canvas" width="480" height="640" aria-label="${t("Bag photo crop preview")}"></canvas></div><div id="photo-adjust" hidden><label>${t("Zoom")}<input id="photo-zoom" type="range" min="1" max="3" step="0.01" value="1"></label><label>${t("Horizontal position")}<input id="photo-x" type="range" min="0" max="1" step="0.01" value="0.5"></label><label>${t("Vertical position")}<input id="photo-y" type="range" min="0" max="1" step="0.01" value="0.5"></label></div><p class="field-help" id="photo-status">${t("JPEG, PNG or WebP, up to 15 MB. Photos stay here and are included in your backup.")}</p><div class="actions"><button type="button" id="use-photo" class="primary" ${existing?'':'disabled'}>${t("Save photo")}</button><button type="button" id="remove-photo">${t("Remove photo")}</button></div>`);
 $('#dialog').classList.add('photo-dialog');morphSheet(source);
 const canvas=$('#photo-canvas'),ctx=canvas.getContext('2d');
 const draw=()=>{if(!img)return;const zoom=Number($('#photo-zoom').value),ratio=Math.max(480/img.width,640/img.height)*zoom,w=480/ratio,h=640/ratio;ctx.drawImage(img,(img.width-w)*Number($('#photo-x').value),(img.height-h)*Number($('#photo-y').value),w,h,0,0,480,640);let q=.86;do{encoded=canvas.toDataURL('image/jpeg',q);q-=.12;}while(encoded.length>240000&&q>.1);if(encoded.length>240000){encoded='';$('#photo-status').textContent=t("This photo is too detailed to save. Try a closer crop.");}else $('#photo-status').textContent=t("Ready · cropped and compressed on this device.");$('#use-photo').disabled=!encoded;};
 for(const id of ['photo-zoom','photo-x','photo-y'])$('#'+id).oninput=draw;
 if(existing){const preview=new Image();preview.onload=()=>ctx.drawImage(preview,0,0,480,640);preview.src=existing;}
 $('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++serial;$('#use-photo').disabled=true;encoded='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error(t("Choose a JPEG, PNG or WebP photo under 15 MB."));const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error(t("Could not read this photo.")));reader.readAsDataURL(file);});const decoded=new Image();await new Promise((resolve,reject)=>{decoded.onload=resolve;decoded.onerror=()=>reject(Error(t("This photo could not be opened. Try a JPEG or PNG.")));decoded.src=url;});if(token!==serial||!canvas.isConnected||!$('#dialog').open)return;if(decoded.width*decoded.height>60000000)throw Error(t("Choose a photo smaller than 60 megapixels."));img=decoded;$('#photo-zoom').value=1;$('#photo-x').value=$('#photo-y').value=.5;$('#photo-adjust').hidden=false;draw();}catch(error){$('#photo-status').textContent=error.message;}};
 const apply=async image=>{if(savingPhoto)return;savingPhoto=true;const button=$('#use-photo'),remove=$('#remove-photo');button.disabled=remove.disabled=true;try{if(beanId)await storePhoto(beanId,image);else onUse(image);await closeSheet();if(beanId)render();}catch(error){toast(error.message);}finally{savingPhoto=false;button.disabled=!encoded;remove.disabled=false;}};
 $('#use-photo').onclick=()=>{if(encoded)apply(encoded);};$('#remove-photo').onclick=()=>apply('');
}

// A single human action produces one durable record, even during a slow disk write.
const pendingForms=new WeakSet();
function singleSubmit(handler){return async event=>{event.preventDefault();const form=event.currentTarget;if(pendingForms.has(form))return;pendingForms.add(form);const buttons=[...form.querySelectorAll('button[type=submit],button:not([type])')],states=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{await handler(event);}finally{pendingForms.delete(form);buttons.forEach((b,i)=>b.disabled=states[i]);}};}

const tasteUI=createTasteUI({data,save,modal,escape,toast,render,bag:beanObject,download:downloadJSON,singleSubmit,
 close:()=>$('#dialog').close(),
 async saveMany(values){const rows=values.map(([kind,payload])=>({id:payload.id,kind,created:payload.created||new Date().toISOString(),payload:JSON.stringify(payload)}));await merge(rows,scope());entries=await list(scope());scheduleAccountSync();},
 async removeRecord(id){await new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');tx.objectStore('entries').delete([scope(),id]);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});entries=await list(scope());scheduleAccountSync();},
 importShared:()=>nativeSend('importShared'),
 planStart:(candidate,profile)=>tasteBrewStart(candidate,{beans:data('bean'),reviews:data('taste-review'),profile,brews:data('brew'),equipment:data('equipment'),selectedEquipment:selected.equipment}),
 startBean(bean,profile,start){if(!canReplaceBrew()){location.hash='beans';return;}selected.bean=bean.id;selected.preference=start.preference;const setup=start.setup;if(setup){selected.equipment=setup.id;selected.dose=start.dose;selected.drink=start.drink;}recipe=null;elapsed=0;timerStart=null;location.hash=setup?'brew':'equipment';render();if(!setup)toast('Your bag is saved. Add a compatible setup to start brewing.');else if(start.reference)toast(`Starting with your ${start.dose} g dose and taste preference from ${start.reference.bean}. Dial in this new bag separately.`);}
});

const circleUI=createCircleUI({account:()=>accountUI,data,save,modal,close:()=>$('#dialog').close(),escape,toast,bag:beanObject,singleSubmit,photo:bagPhoto,canStart:canReplaceBrew,renderSharedImage:brew=>cupRecordUI.renderSharedImage(brew),
 async removeRecord(id){await new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');tx.objectStore('entries').delete([scope(),id]);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});entries=await list(scope());scheduleAccountSync();},
 start(bean,start){selected.inspiredBy=start.inspiredBy;selected.bean=bean.id;selected.equipment=start.setup.id;selected.dose=start.dose;selected.drink=start.drink;selected.preference=start.preference;recipe=null;timerStart=null;elapsed=0;location.hash='brew';render();}
});

