function studioEquipment(form,onEdit){
 const extra=form.querySelector(".setup-confirm"),button=extra.querySelector("button.primary"),details=document.createElement("details");details.className="setup-optional";details.innerHTML=`<summary>${t("Brewing details · optional for now")}</summary><p class="field-help">${t("Save your models now. Confirm the basket and dose before your first recipe.")}</p>`;button.remove();extra.before(details);details.append(extra);form.append(button);
 const panel=form.closest('.panel');editorForm(panel,'Make it yours.','YOUR EVERYDAY SETUP');panel.querySelector('h2')?.remove();
 for(const section of form.querySelectorAll('.equipment-selection')){const kind=section.querySelector('#choose-grinder')?'grinder':'brewer';section.insertAdjacentHTML('afterbegin',`<div class="selection-object">${equipmentObject(kind)}</div>`);}
 const setups=data('equipment');
 $('#main').innerHTML=`<div class="studio-heading"><div><p class="eyebrow">${t("THE COFFEE COUNTER")}</p><h1>${t("Your everyday pair.")}</h1></div><button type="button" class="round-add" id="new-setup" aria-label="${t("Add a setup")}">+</button></div><p class="studio-intro">${t("A familiar setup. One less thing to think about.")}</p><div class="counter-list">${setups.map(e=>`<article class="counter-pair item"><div class="counter-scenery"><div>${equipmentObject(e.method==='v60'?'v60':'brewer')}<small>${t("BREWER")}</small><h2>${escape(e.name)}</h2></div><span class="pair-plus">+</span><div>${equipmentObject(/1zpresso|k-ultra|zp6|timemore|comandante|c40|hand/i.test(e.grinder)?'hand-grinder':'grinder')}<small>${t("GRINDER")}</small><h2>${escape(e.grinder)}</h2></div></div><div class="counter-base"><span>${escape(t(methods[e.method]))} <i>·</i> ${e.confirmed&&e.maxDose>0?e.minDose+"–"+e.maxDose+" "+t("g"):t("Models saved")}</span><button type="button" data-edit-setup="${e.id}" class="text-button">${t("Edit setup")}</button><button type="button" data-use-setup="${e.id}" class="primary">${selected.equipment===e.id?t("Ready to brew"):t("Use this setup")} <span>↗</span></button></div><details class="counter-notes"><summary>${t("Your setup notes")}</summary>${e.calibration?`<p>${escape(t('Grind reference: {value}',{value:e.calibration}))}</p>`:''}<p>${escape(e.preparationNote||'')}${e.waterNote?' · '+escape(e.waterNote):''}</p><p class="field-help">${t("Changed your basket, burrs or zero point? Add a new setup to keep old cups accurate.")}</p></details></article>`).join('')||`<section class="counter-empty"><div class="empty-pair">${equipmentObject('brewer')}${equipmentObject('grinder')}</div><h2>${t("A little space for your ritual.")}</h2><p>${t("Add the brewer and grinder you use.")}<br>${t("We’ll keep their settings together.")}</p><button type="button" class="primary" id="build-setup">${t("Build your setup")} <span>↗</span></button></section>`}</div><p class="studio-footnote">${t("Illustrations are guides. Your exact model is in the details.")}</p>`;
 $('#new-setup').onclick=()=>onEdit(null);if($('#build-setup'))$('#build-setup').onclick=()=>onEdit(null);
 document.querySelectorAll('[data-edit-setup]').forEach(b=>b.onclick=()=>onEdit(setups.find(e=>e.id===b.dataset.editSetup)));
 document.querySelectorAll('[data-use-setup]').forEach(b=>b.onclick=()=>{if(!canReplaceBrew())return;const e=setups.find(x=>x.id===b.dataset.useSetup);selected.equipment=e.id;selected.dose=setupDose(e);selected.drink=e.method;recipe=null;elapsed=0;timerStart=null;location.hash='brew';});
}
