 const heading=$('.lead');heading.className='studio-heading';heading.innerHTML=`<div><p class="eyebrow">${t("YOUR COFFEE SHELF")}</p><h1>${t("Good things, waiting.")}</h1></div><button type="button" id="new-bag" class="round-add" aria-label="${t("Add a bag")}">+</button>`;
