 const tiles=[...document.querySelectorAll('.bean-tile')];for(const tile of tiles){const paragraphs=[...tile.querySelectorAll(':scope>p')];const info=document.createElement('details');info.className='bag-info';info.innerHTML=`<summary>${t("Bag details")}</summary>`;for(const p of paragraphs.slice(1))info.append(p);info.append(tile.querySelector('[data-photo-bean]'));tile.append(info);}
 const add=document.createElement('button');add.type='button';add.className='shelf-add';add.innerHTML=`<span>+</span><strong>${t("A fresh bag")}</strong><small>${t("Make room for something new")}</small>`;add.onclick=()=>onEdit(null);$('.bean-shelf').append(add);
 $('#new-bag').onclick=()=>onEdit(null);document.querySelectorAll('[data-edit-bean]').forEach(b=>b.onclick=()=>onEdit(data('bean').find(x=>x.id===b.dataset.editBean)));
