function attachLabelReader(form,kind,target) {
 const isBean=kind==='bean',isGrinder=target==='grinder';
 const box=document.createElement('div');box.className='tm-label-reader';
 const photoLabel=isBean?'Photograph the bag to read bean details':isGrinder?'Photograph grinder front or model plate':'Photograph machine front or model plate';
 box.innerHTML=`<p class="reader-title">${t(photoLabel)}</p><div class="reader-choices"><button type="button" class="reader-photo" ${photoRecognitionAvailable()?'':'disabled'}>${t('Read a photo')}</button></div><input type="file" accept="image/jpeg,image/png,image/webp" hidden><p class="field-help" role="status">${globalThis.DAYCUP_NATIVE?t("Read on this iPhone. The photo stays on your device."):photoRecognitionAvailable()?t("Optional photo reading. Review the result before saving."):t("Photo recognition is available in the iPhone app. Enter details manually on the web.")}</p>`;
 const manual=form.querySelector(isBean?'#choose-beans':isGrinder?'#choose-grinder':'#choose-brewer');
 const section=manual?.closest('.equipment-selection');
 if(section)section.append(box);else form.prepend(box);
 box.querySelector('.reader-photo').onclick=()=>box.querySelector('input').click();
 if(manual){manual.classList.add('reader-manual');manual.textContent=t('Choose or enter manually');box.querySelector('.reader-choices').append(manual);}
 let serial=0;
 box.querySelector('input').onchange=async event=>{const file=event.target.files[0];if(!file)return;const token=++serial,status=box.querySelector('[role=status]');status.textContent=t("Reading the label...");try{const result=await recognizeCoffeePhoto(file,kind);if(!form.isConnected||serial!==token)return;if(kind==='bean'){for(const key of ['name','roast','origin','process','batch'])if(result[key]&&form.elements[key])form.elements[key].value=result[key];if(form.elements.origin)$('#origin-choice').textContent=result.origin||t('Choose country or region');if(form.elements.process)$('#process-choice').textContent=result.process||t('Choose processing method');}else{const field=target==='grinder'?'grinder':'name';form.elements[field].value=result.name||'';form.elements[field].dispatchEvent(new Event('input'));}status.textContent=t('Read: {text}. Check the exact model and all details; nothing has been saved.',{text:result.text||t('No clear text')});if(form.elements.confirmed)form.elements.confirmed.checked=false;}catch(error){status.textContent=t(error.message);}};
}

