 const heading=$('.lead')||$('.studio-heading');heading.className='studio-heading';heading.innerHTML=`<div><p class="eyebrow">${t("YOUR BREW JOURNAL")}</p><h1>${t("One cup at a time.")}</h1></div><a class="button" href="#circle">${t("Coffee circle ↗")}</a>`;
 if(!$('.you-tabs'))heading.insertAdjacentHTML('afterend',`<nav class="you-tabs" aria-label="${t("Your coffee")}"><a href="#history" aria-current="page">${t("Your cups")}</a><a href="#taste">${t("Your taste")}</a><a href="#equipment">${t("Your setup")}</a></nav>`);
