async function withBusy(task){if(busy)return;busy=true;document.querySelectorAll('#main button').forEach(b=>b.disabled=true);try{await task();}catch(error){toast(error.message);}finally{busy=false;render();}}
function downloadJSON(value,name){
 if(globalThis.DAYCUP_NATIVE){nativeSend('export',{name,text:JSON.stringify(value,null,2)});return;}
 const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function dataPage(){
 $('#main').innerHTML=`<div class="lead"><p class="eyebrow">${t('YOUR COFFEE, YOUR RECORDS')}</p><h1>${t('On this device. Yours.')}</h1><p class="muted">${t('{setups} setups · {batches} batches · {brews} brews',{setups:data('equipment').length,batches:data('bean').length,brews:data('brew').length})}</p></div><div class="grid"><section class="panel"><h2>${t('Your library works offline.')}</h2><p>${t('Recipes run on this device. Cloud sync starts only after you sign in and choose your private cloud library.')}</p><p class="hint">${t('Guest records stay on this device. Use account sync across devices, or keep a separate exported backup.')}</p><div class="actions"><button class="primary" id="export">${t('Export backup')}</button><button id="import">${t('Import backup')}</button></div><input id="file" type="file" accept="application/json,.json" hidden><p class="muted">${t('Backups include your private notes and history. Share them only with people you trust. Import merges compatible records without duplicates or silent overwrites.')}</p><button id="persist">${t('Request persistent storage')}</button><p class="muted">${t('Your browser can decline this request. Browser cleanup, private browsing and device loss can still remove data; keep a separate backup.')}</p><button class="danger" id="clear-local">${t('Clear this local library')}</button></section><div><section class="panel"><h2>${t('Two ways to keep DayCup')}</h2><p><strong>${t('On the web:')}</strong> ${t('open DayCup at its SideCourt address. On a phone, use Add to Home Screen to keep it as an app icon; on a desktop browser, use Install app. After the first visit it works offline.')}</p><p><strong>${t('As a file:')}</strong> ${t('keep the standalone DayCup.html file and open it in a desktop browser. Everything it needs is included. If your browser blocks file storage, use the included loopback launcher instead.')}</p><p class="muted">${t('Records stay in the browser where you saved them. Each address, browser and device has its own library; move records with Export and Import.')}</p><p class="muted">${t("DayCup")} ${escape(appVersion)} · ${escape(knowledgeVersion)} · ${t('Espresso, Americano, iced Americano and V60. Actual basket capacity and grinder calibration still need your confirmation. A software test is not a taste test.')}</p><p class="muted"><a href="${globalThis.DAYCUP_BUNDLE?'#privacy':'privacy.html'}">${t('Privacy & data')}</a></p></section><section class="panel"><h2>${t('Previous local libraries')}</h2><p class="muted">${t('An older version may have kept records under an account on this same browser. They remain separate and untouched. No password or server connection is used here.')}</p><button id="legacy">${t('Recover a library on my device')}</button><p class="muted">${t('Use only your own browser profile. Local records are not encrypted or protected from other people using this profile.')}</p></section></div></div>`;
 document.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>{switchLanguage(button.dataset.language);});
 $('#export').onclick=()=>downloadJSON({schema:1,entries},'DayCup-backup-'+localToday()+'.json');
 $('#import').onclick=()=>globalThis.DAYCUP_NATIVE?nativeSend('import'):$('#file').click();$('#file').onchange=e=>{const file=e.target.files[0];if(!file)return;withBusy(async()=>{if(file.size>16000000)throw Error(t('The backup exceeds 16 MB.'));const archive=JSON.parse(await file.text());if(archive.schema!==1)throw Error(t('This backup version is not supported.'));await merge(archive.entries,scope());entries=await list(scope());scheduleAccountSync();toast(t('Backup imported. Matching records were not duplicated.'));});};
 $('#persist').onclick=async()=>{try{const granted=await navigator.storage?.persist?.();toast(t(granted?t("Persistent storage granted. Still keep a backup."):t("Persistent storage was not granted by this browser. Export a backup regularly.")));}catch{toast(t('This browser cannot grant persistent storage here. Export a backup.'));}};
 $('#clear-local').onclick=()=>{modal(`<h2>${t('Clear this local library?')}</h2><p>${t('Export a backup first. This clears the current local library only. An existing cloud copy is managed separately in Account & sync.')}</p><button class="danger" id="confirm-clear">${t('Permanently clear this library')}</button>`);$('#confirm-clear').onclick=()=>withBusy(async()=>{await cupRecordUI.flush();clearTimeout(accountSyncTimer);cupRecordUI.resetSession();const clearingScope=scope();if(accountUI.active)await accountUI.signOut();await clearScope(clearingScope);if(clearingScope.startsWith('account:'))localStorage.removeItem(accountCacheKey(clearingScope.slice(8)));entries=await list(scope());grindDrafts.clear();circleUI.clearPreferences();recipe=null;timerStart=null;$('#dialog').close();toast(t('The current local library has been cleared.'));});};
 $('#legacy').onclick=async()=>{try{
  const rows=await new Promise((resolve,reject)=>{const r=db.transaction('entries').objectStore('entries').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  const groups=[...new Set(rows.map(x=>x.scope))].filter(x=>x!==scope()&&!String(x).startsWith('account:'));
  modal(`<h2>${t('Recover only your own records')}</h2><p>${t('Local libraries are not a login security boundary. Select a library you own. Exporting does not merge or delete it. Import that backup separately to copy it into the current library.')}</p>${groups.map((g,i)=>`<p><button data-legacy="${i}">${t('Export previous library {number} · {count} records',{number:i+1,count:rows.filter(x=>x.scope===g).length})}</button></p>`).join('')||'<p>'+t('No previous account libraries were found on this browser and address.')+'</p>'}`);
  document.querySelectorAll('[data-legacy]').forEach(button=>button.onclick=()=>{const g=groups[Number(button.dataset.legacy)];if(confirm(t('I own this local library and want to export its private records.')))downloadJSON({schema:1,entries:rows.filter(x=>x.scope===g).map(({scope,...entry})=>entry)},'DayCup-previous-library-'+localToday()+'.json');});
 }catch(error){toast(error.message);}};
 studioData();
 if(!globalThis.DAYCUP_BUNDLE&&photoRecognitionAvailable()){const section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>${t("Optional photo reading")}</h2><p>${t("Your coffee library works without AI. If you have a DayCup invitation, connect photo reading here. Photos are sent only when you choose to read one.")}</p><form id="tm-connect"><label>${t("Invitation code")}<input name="invite" type="password" autocomplete="off" required maxlength="200"></label><button>${t("Connect photo reading")}</button></form>`;$('.data-studio').append(section);$('#tm-connect').onsubmit=singleSubmit(async e=>{try{await connectPhotoService(e.target.elements.invite.value);e.target.reset();toast(t("Photo reading connected. Your library remains on this device."));}catch(error){toast(error.message);}});}
 if(globalThis.DAYCUP_NATIVE)nativeDataPage();
 {const langSection=document.createElement('section');langSection.className='panel language-panel';langSection.innerHTML=`<h2>${t('Language')}</h2><div class="actions">${Object.entries(languages).map(([code,label])=>`<button data-language="${code}" aria-pressed="${currentLanguage()===code}">${label}</button>`).join('')}</div>`;$('#main').prepend(langSection);langSection.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>switchLanguage(button.dataset.language));}
 const accountPanel=document.createElement('section');accountPanel.className='account-data-link';accountPanel.innerHTML=`<button id="open-account">${t('Account & sync')} <span aria-hidden="true">›</span></button>`;$('#main').prepend(accountPanel);$('#open-account').onclick=()=>accountUI.open();

}
