function nativePrivacyPage(){
 $('#main').innerHTML=`<p class="eyebrow">${t("PRIVACY & LOCAL DATA")}</p><h1>${t("Your coffee, your choices")}</h1><p>${t("DayCup calculates recipes on your iPhone without OpenAI requests. Cloud storage starts only after you sign in and choose it. Account sync and public Circle sharing are separate choices.")}</p><p>${t("Taste Match keeps your preferences, reflections, shortlist and received shared cups on your iPhone. Apple Vision reads selected label photos on the device; nothing is sent to OpenAI. Review every result before saving.")}</p><p>${t("Your library is private by default. Sign in with your DayCup / SideCourt account and choose a public name to join TheClub. Only the saved cups you explicitly publish, their finished share images and captions become public. Private notes and other history are excluded. You can cheer, follow, hide a person, report a concern, remove your own shared cups or leave TheClub. Reports are stored for review. Copies saved by others cannot be recalled. TheClub does not use OpenAI tokens.")}</p><p>${t("Your equipment, beans, photos, recipes and notes are stored in this app. Photos you select are cropped and compressed on your device. Removing a photo removes it from the current library; older backups keep their original photos.")}</p><p>${t('Backups include your photos, private notes, preferences and reflection revisions in readable JSON. New Taste Match records require DayCup 2.4 or newer to restore. You choose where to save or share them using the iOS share sheet. Files or cloud services you select follow their own privacy policies.')}</p><p>${t("Your iPhone may include app data in its system backups, according to your device settings. DayCup offers optional private cloud sync through your SideCourt account. Deleting the app or losing your phone can remove local records. Save a separate backup in Files.")}</p><p>${t("Manufacturer and other external links open only when you tap them. Those websites have their own privacy policies.")}</p><p>${t("Use Google or email to sign in or register with the shared SideCourt account service. Choose to open a private cloud library, start an empty one or bring your guest records. Your activated library reopens on this device and syncs changes; guest data is never uploaded automatically. From My account you can sign out, delete the cloud copy or delete your DayCup account data and TheClub profile. Deleting DayCup data keeps the shared SideCourt sign-in and other products intact. A content-free revision marker prevents an older device from restoring erased data. Export a backup before deletion.")}</p><h2>${t('Your cup image & city')}</h2><p>${t('Share designs and their photos stay on this device, travel in backups and require DayCup 2.8 or newer. Editing an image never changes your measured cup.')}</p><p>${t("A share image is created on your iPhone from one saved cup and the words you add. It excludes private notes. Choosing a city enables approximate city-to-city distances; no GPS or home location is collected. Your city stays on this device unless you explicitly include it with a public cup.")}</p><a class="button" href="#data">${t("Back to settings")}</a>`;
}
function nativeDataPage(){
 const primary=$('.data-primary');if(primary){const hint=primary.querySelector('.hint');if(hint)hint.textContent=t("Your library stays on this iPhone. Save a backup to Files before replacing your phone or deleting the app.");}
 const persist=$('#persist');if(persist){const note=persist.nextElementSibling;if(note)note.textContent=t("Deleting DayCup or losing this iPhone can remove your library. Keep a separate backup in Files.");persist.hidden=true;}
 const sections=[...$('#main').querySelectorAll('section')];const install=sections.find(x=>x.querySelector('h2')?.textContent===t('Two ways to keep DayCup'));if(install)install.innerHTML=`<h2>${t("Made for your daily cup.")}</h2><p>${t("DayCup works offline. Your equipment, coffee bags, photos and brewing notes stay in this app.")}</p><p>${t("Use Keep a backup to save your library to Files or share it. Bring it back restores a DayCup JSON backup, including backups from the web edition.")}</p><p>DayCup ${appVersion} · ${t('Espresso, Americano, iced Americano and V60.')}</p><a href="#privacy">${t("Privacy & data")}</a>`;
}
function nativeSend(action,payload={}){if(!globalThis.DAYCUP_NATIVE)return;globalThis.webkit?.messageHandlers?.daycup?.postMessage({action,...payload});}
function nativeCheckpoint(){
 if(!globalThis.DAYCUP_NATIVE)return;
 try{if(recipe)localStorage.setItem('daycup-active-cup',JSON.stringify({scope:scope(),recipe,selected,elapsed,timerStart,grindDrafts:[...grindDrafts]}));else localStorage.removeItem('daycup-active-cup');}catch(error){toast(t("Your active timer could not be saved. Finish this cup before closing DayCup."));}
 nativeSend('timer',{running:!!timerStart});
}
function restoreNativeCup(){
 try{const raw=localStorage.getItem('daycup-active-cup');if(!raw)return;const v=JSON.parse(raw);if((v.scope||'guest')!==scope())return;if(!v.recipe?.equipment?.id||!v.recipe?.bean?.id||!Number.isFinite(v.elapsed)||v.elapsed<0||v.timerStart!==null&&!Number.isFinite(v.timerStart))return;if(!data('equipment').some(e=>e.id===v.recipe.equipment.id)||!data('bean').some(b=>b.id===v.recipe.bean.id))return;recipe=v.recipe;selected=v.selected;elapsed=v.elapsed;timerStart=v.timerStart;if(Array.isArray(v.grindDrafts))for(const pair of v.grindDrafts){if(Array.isArray(pair)&&pair.length===2&&typeof pair[0]==='string'&&typeof pair[1]==='string')grindDrafts.set(...pair);}nativeSend('timer',{running:!!timerStart});}catch(error){toast(t("The unfinished cup could not be restored. Your saved library is still available."));}
}
if(globalThis.DAYCUP_NATIVE){
 document.documentElement.classList.add('native-app');
 globalThis.daycupNative={
  navigate(route){if(!['brew','beans','history','taste','circle','equipment','data','privacy'].includes(route))return;location.hash=route;},
  async importShared(text){try{await tasteUI.importShared(text);}catch(error){toast(error.message);}},
  async importBackup(text){try{if(new Blob([text]).size>16000000)throw Error('The backup exceeds 16 MB.');const archive=JSON.parse(text);if(archive.schema!==1)throw Error('This backup version is not supported.');await merge(archive.entries,scope());entries=await list(scope());render();toast('Backup restored. Matching records were not duplicated.');nativeSend('haptic');}catch(error){toast(error.message);}},
  checkpoint:nativeCheckpoint,
  notify(message){toast(message);}
 };
 document.addEventListener('visibilitychange',nativeCheckpoint);

}

